item.aggregated_output:
    check_live: bool = True,
    verify_files: bool = True,
) -> dict[str, Any]:
    """Validate the pinned local gateway without exposing credentials or provider accounts."""
    errors: list[str] = []
    try:
        raw_profile = profile_path.read_bytes()
        profile = json.loads(raw_profile.decode("utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        return {
            "ok": False,
            "profile": str(profile_path),
            "profile_sha256": None,
            "errors": [f"invalid gateway profile: {exc}"],
        }
    if not isinstance(profile, dict):
        return {
            "ok": False,
            "profile": str(profile_path),
            "profile_sha256": hashlib.sha256(raw_profile).hexdigest(),
            "errors": ["gateway profile must be a JSON object"],
        }

    profile_sha256 = hashlib.sha256(raw_profile).hexdigest()
    if profile.get("schema") != "hl-loop-gateway-profile/v1":
        errors.append("gateway profile schema mismatch")
    if profile.get("gateway_id") != "opencodex":
        errors.append("gateway_id must be opencodex")
    host = profile.get("host")
    port = profile.get("port")
    base_url = profile.get("base_url")
    health_url = profile.get("health_url")
    if host != "127.0.0.1" or not isinstance(port, int) or not (1 <= port <= 65535):
        errors.append("gateway must use an explicit 127.0.0.1 TCP endpoint")
    if base_url != f"http://{host}:{port}/v1":
        errors.append("gateway base_url does not match its loopback host/port")
    if health_url != f"http://{host}:{port}/healthz":
        errors.append("gateway health_url does not match its loopback host/port")

    pinned_files: dict[str, Any] = {}
    for label, path, expected_hash in _gateway_file_specs(profile):
        valid_hash = len(expected_hash) == 64 and all(char in "0123456789abcdef" for char in expected_hash)
        if not str(path) or not valid_hash:
            errors.append(f"gateway profile has an invalid {label} path/hash")
            pinned_files[label] = {"path": str(path), "exists": False, "sha256": None, "pinned": False}
            continue
        exists = path.is_file()
        actual_hash = _sha256_file(path) if exists and verify_files else None
        pinned = exists and (actual_hash == expected_hash if verify_files else True)
        if not exists:
            errors.append(f"pinned gateway file is missing: {label}")
        elif verify_files and not pinned:
            errors.append(f"pinned gateway file hash mismatch: {label}")
        pinned_files[label] = {
            "path": str(path), "exists": exists, "sha256": actual_hash, "pinned": pinned,
        }

    package = profile.get("package") if isinstance(profile.get("package"), dict) else {}
    package_json_path = Path(str(package.get("package_json", "")))
    package_identity: dict[str, Any] = {
        "name": package.get("name"), "version": package.get("version"), "repository": package.get("repository"),
    }
    if package_json_path.is_file():
        try:
            package_doc = json.loads(package_json_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            errors.append(f"invalid pinned gateway package.json: {exc}")
        else:
            repository = package_doc.get("repository")
            if isinstance(repository, dict):
                repository = repository.get("url")
            normalized_repository = str(repository or "").removeprefix("git+").removesuffix(".git")
            if package_doc.get("name") != package.get("name"):
                errors.append("gateway package name does not match the profile")
            if package_doc.get("version") != package.get("version"):
                errors.append("gateway package version does not match the profile")
            if normalized_repository != str(package.get("repository", "")).removesuffix(".git"):
                errors.append("gateway package repository does not match the profile")

    effective = profile.get("effective_config") if isinstance(profile.get("effective_config"), dict) else {}
    effective_path = Path(str(effective.get("path", "")))
    effective_surface: dict[str, Any] = {}
    if not effective_path.is_file():
        errors.append("OpenCodex effective config is missing")
    else:
        try:
            effective_doc = json.loads(effective_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            errors.append(f"invalid OpenCodex effective config: {exc}")
        else:
            configured_models = effective_doc.get("subagentModels")
            required_models = effective.get("required_subagent_models")
            effective_surface = {
                "port": effective_doc.get("port"),
                "multi_agent_mode": effective_doc.get("multiAgentMode"),
                "multi_agent_guidance_enabled": effective_doc.get("multiAgentGuidanceEnabled"),
                "required_subagent_models_present": (
                    isinstance(configured_models, list)
                    and isinstance(required_models, list)
                    and all(model in configured_models for model in required_models)
                ),
            }
            if effective_surface["port"] != port:
                errors.append("OpenCodex effective config port does not match the gateway profile")
            if effective_surface["multi_agent_mode"] != effective.get("multi_agent_mode"):
                errors.append("OpenCodex multi-agent mode does not match the gateway profile")
            if effective_surface["multi_agent_guidance_enabled"] is not effective.get(
                "multi_agent_guidance_enabled"
            ):
                errors.append("OpenCodex multi-agent guidance state does not match the gateway profile")
            if effective_surface["required_subagent_models_present"] is not True:
                errors.append("OpenCodex subagent roster is missing a required HL-LOOP model")

    listening: bool | None = None
    health: dict[str, Any] = {}
    process: dict[str, Any] = {}
    if check_live and isinstance(host, str) and isinstance(port, int):
        listening = tcp_listening(host, port)
        if not listening:
            errors.append(f"OpenCodex is not listening on {host}:{port}")
        if listening and isinstance(health_url, str):
            try:
                with urllib.request.urlopen(health_url, timeout=2.0) as response:
                    health = json.loads(response.read().decode("utf-8"))
            except (OSError, UnicodeError, ValueError, urllib.error.URLError) as exc:
                errors.append(f"OpenCodex health endpoint failed: {exc}")
                health = {}
        expected_health = profile.get("health_identity") if isinstance(profile.get("health_identity"), dict) else {}
        for field in ("status", "service", "version"):
            if health.get(field) != expected_health.get(field):
                errors.append(f"OpenCodex health identity mismatch: {field}")
        health_pid = health.get("pid")
        if not isinstance(health_pid, int) or not pid_alive(health_pid):
            errors.append("OpenCodex health endpoint did not identify a live process")
        else:
            process_path = _process_image_path(health_pid)
            expected_process = Path(str(profile.get("service", {}).get("process_executable", "")))
            process = {"pid": health_pid, "image": str(process_path) if process_path else None}
            if os.name == "nt" and (
                process_path is None
                or normalize_windows_path(process_path) != normalize_windows_path(expected_process)
            ):
                errors.append("OpenCodex health PID does not run the pinned process image")

    surface_sha256 = hashlib.sha256(
        json.dumps(effective_surface, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    report = {
        "ok": not errors,
        "gateway_id": profile.get("gateway_id"),
        "provider_id": profile.get("provider_id"),
        "provider_name": profile.get("provider_name"),
        "base_url": base_url,
        "wire_api": profile.get("wire_api"),
        "health_url": health_url,
        "profile": str(profile_path),
        "profile_sha256": profile_sha256,
        "package": package_identity,
        "pinned_files": pinned_files,
        "effective_surface": effective_surface,
        "effective_surface_sha256": surface_sha256,
        "listening": listening,
        "health": {key: health.get(key) for key in ("status", "service", "version", "pid", "port")},
        "process": process,
        "errors": errors,
    }
    report["instance_sha256"] = hashlib.sha256(
        json.dumps(
            {
                "profile_sha256": profile_sha256,
                "effective_surface_sha256": surface_sha256,
                "health": report["health"],
                "process": process,
            },
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return report


def _load_toml(path: Path, errors: list[str]) -> dict[str, Any]:
    try:
        return tomllib.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, tomllib.TOMLDecodeError) as exc:
        errors.append(f"invalid TOML {path}: {exc}")
        return {}


def _check_project_trust(global_doc: dict[str, Any], root: Path) -> tuple[bool, str]:
    projects = global_doc.get("projects")
    if not isinstance(projects, dict):
        return False, "global config has no projects table"
    wanted = normalize_windows_path(root)
    for key, value in projects.items():
        if normalize_windows_path(key) != wanted or not isinstance(value, dict):
            continue
        level = str(value.get("trust_level", "")).lower()
        return level == "trusted", f"project trust_level={level or 'missing'}"
    return False, "project trust entry not found"

def inspect_installation(
    root: Path,
    python_exe: Path,
    global_config: Path,
    *,
    check_proxy: bool = True,
    gateway_profile: Path | None = None,
) -> dict[str, Any]:
    """Validate the Desktop project package without reading credential files."""
    root = root.resolve()
    errors: list[str] = []
    warnings: list[str] = []
    config_dir = root / ".codex"
    config = _load_toml(config_dir / "config.toml", errors)

    if (config.get("model"), config.get("model_reasoning_effort")) != EXPECTED_HOST:
        errors.append("Desktop host must be gpt-5.6-sol/high")
    if config.get("approval_policy") != "never":
        errors.append("Desktop project approval_policy must be never")
    agents = config.get("agents", {})
    if not isinstance(agents, dict) or agents.get("enabled") is not True:
        errors.append("project agents must be enabled")
    features = config.get("features", {})
    if not isinstance(features, dict) or features.get("multi_agent") is not True:
        errors.append("features.multi_agent must be enabled")
    if not isinstance(features, dict) or features.get("hooks") is not True:
        errors.append("features.hooks must be enabled")

    role_results: dict[str, Any] = {}
    for role, expected in EXPECTED_ROLES.items():
        path = config_dir / "agents" / f"{role}.toml"
        doc = _load_toml(path, errors)
        actual = (doc.get("model"), doc.get("model_reasoning_effort"))
        role_results[role] = {"model": actual[0], "reasoning_effort": actual[1]}
        if actual != expected:
            errors.append(f"{role} must be {expected[0]}/{expected[1]}")

    hooks_path = config_dir / "hooks.json"
    try:
        hooks_doc = json.loads(hooks_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        errors.append(f"invalid hooks JSON {hooks_path}: {exc}")
        hooks_doc = {}

    hooks = hooks_doc.get("hooks", {}) if isinstance(hooks_doc, dict) else {}
    hook_results: dict[str, Any] = {}
    for event, script_name in EXPECTED_HOOKS.items():
        groups = hooks.get(event, []) if isinstance(hooks, dict) else []
        handlers = [
            handler
            for group in groups if isinstance(group, dict)
            for handler in group.get("hooks", []) if isinstance(handler, dict)
        ]
        commands = [str(h.get("commandWindows") or h.get("command") or "") for h in handlers]
        script = config_dir / "hooks" / script_name
        ok = bool(commands) and any(script_name.lower() in c.lower() for c in commands)
        if not script.is_file():
            errors.append(f"missing hook script: {script}")
            ok = False
        if not ok:
            errors.append(f"{event} does not invoke {script_name}")
        hook_results[event] = {"script": str(script), "configured": ok}

    python_ok = python_exe.is_file()
    if not python_ok:
        errors.append(f"Python runtime missing: {python_exe}")
    elif sys.version_info < (3, 11):
        errors.append("launcher Python must be 3.11 or newer")

    global_doc = _load_toml(global_config, errors)
    trust_ok, trust_detail = _check_project_trust(global_doc, root)
    if not trust_ok:
        errors.append(f"Desktop project is not trusted: {trust_detail}")

    gateway_profile = gateway_profile or (root / "deploy" / "gateway-profile.json")
    gateway = inspect_gateway(gateway_profile, check_live=check_proxy, verify_files=True)
    errors.extend(str(error) for error in gateway.get("errors", []))

    provider_name = global_doc.get("model_provider")
    providers = global_doc.get("model_providers", {})
    provider_doc = providers.get(provider_name, {}) if isinstance(providers, dict) else {}
    base_url = provider_doc.get("base_url") if isinstance(provider_doc, dict) else None
    provider_display_name = provider_doc.get("name") if isinstance(provider_doc, dict) else None
    wire_api = provider_doc.get("wire_api") if isinstance(provider_doc, dict) else None
    if provider_name != gateway.get("provider_id"):
        errors.append(
            f"global model_provider is {provider_name!r}, expected {gateway.get('provider_id')!r}"
        )
    if provider_display_name != gateway.get("provider_name"):
        errors.append("global provider display name does not identify the pinned gateway")
    if base_url != gateway.get("base_url"):
        errors.append("global provider base_url does not match the pinned gateway")
    if wire_api != gateway.get("wire_api"):
        errors.append("global provider wire_api does not match the pinned gateway")

    state_db = global_config.parent / "state_5.sqlite"
    if not state_db.is_file():
        warnings.append(f"Desktop state database not found yet: {state_db}")

    return {
        "schema": "hl-loop-desktop-preflight/v2",
        "generated_at": utc_now(),
        "ok": not errors,
        "root": str(root),
        "host": {"model": config.get("model"), "reasoning_effort": config.get("model_reasoning_effort")},
        "roles": role_results,
        "hooks": hook_results,
        "python": {"path": str(python_exe), "exists": python_ok},
        "provider": {
            "id": provider_name,
            "name": provider_display_name,
            "base_url": base_url,
            "wire_api": wire_api,
        },
        "gateway": gateway,
        "project_trust": {"ok": trust_ok, "detail": trust_detail},
        "state_db": str(state_db),
        "errors": errors,
        "warnings": warnings,
    }


def _line_count(path: Path) -> int:
    try:
        with path.open("rb") as handle:
            return sum(1 for _ in handle)
    except OSError:
        return 0


def observe_state_db(db_path: Path, project_root: Path, limit: int = 200) -> dict[str, Any]:
    """Read Desktop's state database through SQLite read-only mode."""
    if not db_path.is_file():
        return {"available": False, "threads": [], "spawn_edges": [], "route_violations": []}

    target = normalize_windows_path(project_root)
    uri = f"file:{db_path.as_posix()}?mode=ro"
    conn = sqlite3.connect(uri, uri=True, timeout=1.0)
    conn.row_factory = sqlite3.Row
    try:
        names = {row[0] for row in conn.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        if not {"threads", "thread_spawn_edges"}.issubset(names):
            return {
                "available": False,
                "threads": [],
                "spawn_edges": [],
                "route_violations": ["Desktop state DB lacks required tables"],
            }
        root_text = str(project_root.resolve())
        root_variants = {
            root_text,
            root_text.replace("\\", "/"),
            "\\\\?\\" + root_text,
            "//?/" + root_text.replace("\\", "/"),
        }
        marks = ",".join("?" for _ in root_variants)
        rows = conn.execute(
            "SELECT id,cwd,model,reasoning_effort,agent_role,created_at_ms,updated_at_ms "
            f"FROM threads WHERE cwd COLLATE NOCASE IN ({marks}) "
            "ORDER BY recency_at_ms DESC LIMIT ?",
            (*sorted(root_variants), limit),
        ).fetchall()
        threads = [dict(row) for row in rows if normalize_windows_path(row["cwd"]) == target]
        ids = {row["id"] for row in threads}
        edges: list[dict[str, Any]] = []
        if ids:
            marks = ",".join("?" for _ in ids)
            edge_rows = conn.execute(
                f"SELECT parent_thread_id,child_thread_id,status FROM thread_spawn_edges "
                f"WHERE parent_thread_id IN ({marks}) OR child_thread_id IN ({marks})",
                (*ids, *ids),
            ).fetchall()
            edges = [dict(row) for row in edge_rows]
            child_ids = {row["child_thread_id"] for row in edges} - ids
            if child_ids:
                child_marks = ",".join("?" for _ in child_ids)
                child_rows = conn.execute(
                    "SELECT id,cwd,model,reasoning_effort,agent_role,created_at_ms,updated_at_ms "
                    f"FROM threads WHERE id IN ({child_marks})",
                    tuple(child_ids),
                ).fetchall()
                threads.extend(dict(row) for row in child_rows)
    finally:
        conn.close()

    violations: list[str] = []
    for row in threads:
        role = row.get("agent_role")
        expected = EXPECTED_ROLES.get(role) if role else EXPECTED_HOST
        actual = (row.get("model"), row.get("reasoning_effort"))
        if role and expected is None:
            violations.append(f"{row['id']} has unknown agent role {role!r}")
        elif expected and actual != expected:
            violations.append(
                f"{row['id']} role={role or 'host'} routed to {actual[0]}/{actual[1]} "
                f"instead of {expected[0]}/{expected[1]}"
            )

