def _read(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return {}
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}
    return value if isinstance(value, dict) else {}


def _timestamp(value: Any) -> float | None:
    if not isinstance(value, str):
        return None
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00")).timestamp()
    except ValueError:
        return None


def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _current_trust_manifest_sha256(probe_dir: Path) -> str | None:
    manifest = probe_dir.parents[1] / "deploy" / "desktop-hook-trust.json"
    return _sha256(manifest) if manifest.is_file() else None


def _current_gateway_profile_sha256(probe_dir: Path) -> str | None:
    profile = probe_dir.parents[1] / "deploy" / "gateway-profile.json"
    return _sha256(profile) if profile.is_file() else None


def _raw_sha256(value: Any) -> bool:
    return isinstance(value, str) and _RAW_SHA256_RE.fullmatch(value) is not None


def _readonly_attempts_valid(report: dict[str, Any]) -> bool:
    children = report.get("children")
    if not isinstance(children, list) or len(children) != 1 or not isinstance(children[0], dict):
        return False
    rollout = children[0].get("rollout_path")
    if not isinstance(rollout, str) or not Path(rollout).is_file():
        return False
    calls: dict[str, str] = {}
    outputs: dict[str, str] = {}
    try:
        lines = Path(rollout).read_text(encoding="utf-8").splitlines()
        for line in lines:
            if not line.strip():
                continue
            row = json.loads(line)
            if row.get("type") != "response_item":
                continue
            payload = row.get("payload", {})
            call_id = payload.get("call_id")
            if payload.get("type") in {"custom_tool_call", "function_call"}:
                value = payload.get("input", payload.get("arguments"))
                if isinstance(call_id, str) and isinstance(value, str):
                    calls[call_id] = value
            elif payload.get("type") in {"custom_tool_call_output", "function_call_output"}:
                value = payload.get("output")
                if isinstance(value, list):
                    value = "\n".join(
                        str(item.get("text", "")) for item in value if isinstance(item, dict)
                    )
                if isinstance(call_id, str):
                    outputs[call_id] = str(value or "")
    except (OSError, ValueError, TypeError):
        return False
    matched: dict[str, str] = {}
    for call_id, value in calls.items():
        markers = [f"R08_CASE_{index}" for index in range(1, 10) if f"R08_CASE_{index}" in value]
        if len(markers) != 1 or markers[0] in matched:
            continue
        lowered = outputs.get(call_id, "").lower()
        infrastructure_error = any(token in lowered for token in (
            "orchestrator_helper_launch_failed",
            "setup refresh failed to launch helper",
            "sandbox setup failed",
            "createprocesswithlogonw failed",
            "helper copy failed for command-runner",
        ))
        if not infrastructure_error and any(token in lowered for token in (
            "denied", "refused", "read-only", "rejected", "blocked by policy",
            "not permitted", "permission denied", "unauthorizedaccess",
            "access is denied", "諡堤ｻ晁ｮｿ髣ｮ", "隶ｿ髣ｮ陲ｫ諡堤ｻ?,
            "methodinvocationnotsupportedinconstrainedlanguage",
            "constrainedlanguage",
        )):
            matched[markers[0]] = call_id
    return set(matched) == {f"R08_CASE_{index}" for index in range(1, 10)}


def evaluate_g3(doc: dict[str, Any], probe_dir: Path | None = None) -> tuple[str, list[str]]:
    reasons: list[str] = []
    if doc.get("schema") != "hl-loop-g3-readonly-week/v2":
        reasons.append("schema missing or mismatched")
    if doc.get("required_days") != G3_REQUIRED_DAYS:
        reasons.append("required_days must remain 7")
    if doc.get("min_interval_seconds") != G3_MIN_INTERVAL_SECONDS:
        reasons.append("min_interval_seconds must remain 86400")
    if doc.get("only_role") != "v4_scout":
        reasons.append("G3 only_role must be v4_scout")
    days = doc.get("days")
    if not isinstance(days, list) or len(days) != G3_REQUIRED_DAYS:
        reasons.append(f"requires exactly {G3_REQUIRED_DAYS} completed days")
        days = days if isinstance(days, list) else []
    timestamps = [_timestamp(row.get("completed_at")) for row in days if isinstance(row, dict)]
    if any(value is None for value in timestamps):
        reasons.append("every day needs completed_at")
    elif any(
        timestamps[index] - timestamps[index - 1] < G3_MIN_INTERVAL_SECONDS
        for index in range(1, len(timestamps))
    ):
        reasons.append("every adjacent completion must be at least 24 hours apart")
    nonces: set[str] = set()
    auth_baselines: set[str] = set()
    config_baselines: set[str] = set()
    for index, row in enumerate(days):
        if not isinstance(row, dict) or row.get("ok") is not True:
            reasons.append(f"day {index + 1} probe failed")
            continue
        if row.get("day") != index + 1:
            reasons.append(f"day {index + 1} index is missing or out of order")
        started = _timestamp(row.get("started_at"))
        completed = _timestamp(row.get("completed_at"))
        if started is None or completed is None or started > completed:
            reasons.append(f"day {index + 1} has invalid start/completion timestamps")
        nonce = row.get("probe_nonce")
        if not isinstance(nonce, str) or not nonce or nonce in nonces:
            reasons.append(f"day {index + 1} has invalid or duplicate probe nonce")
        else:
            nonces.add(nonce)
        if isinstance(row, dict) and row.get("unauthorized_write_count", 0) != 0:
            reasons.append(f"day {index + 1} has unauthorized writes")
        if isinstance(row, dict) and row.get("route_violations", 0) != 0:
            reasons.append(f"day {index + 1} has route violations")
        if probe_dir is not None:
            expected_path = (probe_dir / f"g3-day-{index + 1:02d}.json").resolve()
            probe_path = row.get("probe_path")
            try:
                candidate = Path(probe_path).resolve() if isinstance(probe_path, str) else None
            except OSError:
                candidate = None
            if candidate != expected_path or not expected_path.is_file():
                reasons.append(f"day {index + 1} is not bound to its canonical probe artifact")
                continue
            report = _read(expected_path)
            checks = report.get("checks")
            report_ok = (
                report.get("schema") == "hl-loop-desktop-readonly-probe/v2"
                and report.get("ok") is True
                and report.get("nonce") == nonce
                and isinstance(report.get("host_thread_id"), str)
                and isinstance(report.get("child_thread_id"), str)
                and isinstance(checks, dict)
                and all(checks.get(name) is True for name in G3_REQUIRED_PROBE_CHECKS)
                and _readonly_attempts_valid(report)
                and report.get("auth_sha256_before") == report.get("auth_sha256_after")
                and report.get("global_config_sha256_before") == report.get("global_config_sha256_after")
                and report.get("trust_manifest_sha256") == _current_trust_manifest_sha256(probe_dir)
                and report.get("gateway_profile_sha256") == _current_gateway_profile_sha256(probe_dir)
            )
            if not report_ok:
                reasons.append(f"day {index + 1} canonical probe artifact is incomplete or invalid")
            else:
                auth_baselines.add(str(report.get("auth_sha256_before")))
                config_baselines.add(str(report.get("global_config_sha256_before")))
    if probe_dir is not None and len(auth_baselines) > 1:
        reasons.append("auth.json baseline changed across G3 days")
    if probe_dir is not None and len(config_baselines) > 1:
        reasons.append("global config baseline changed across G3 days")
    if reasons:
        return "IN_PROGRESS", reasons
    return "PASSED", []


def _checks_true(checks: Any, required: set[str], reasons: list[str]) -> None:
    if not isinstance(checks, dict):
        reasons.append("checks object missing")
        return
    for name in sorted(required):
        if checks.get(name) is not True:
            reasons.append(f"check {name} is not true")


def _write_runs(doc: dict[str, Any], required: int, reasons: list[str]) -> list[dict[str, Any]]:
    runs = doc.get("runs")
    if not isinstance(runs, list) or len(runs) != required:
        reasons.append(f"requires exactly {required} write runs")
        return []
    result = [row for row in runs if isinstance(row, dict)]
    if len(result) != len(runs):
        reasons.append("every write run must be an object")
    for index, row in enumerate(result):
        if row.get("schema") != "hl-loop-desktop-write-run/v2":
            reasons.append(f"write run {index + 1} schema is invalid")
        if row.get("index") != index + 1:
            reasons.append(f"write run {index + 1} index is invalid")
        if row.get("ok") is not True:
            reasons.append(f"write run {index + 1} is not ok")
        _checks_true(row.get("checks"), WRITE_RUN_CHECKS, reasons)
        if not isinstance(row.get("host_thread_id"), str) or not isinstance(row.get("child_thread_id"), str):
            reasons.append(f"write run {index + 1} lacks host/child binding")
        if row.get("auth_sha256_before") != row.get("auth_sha256_after"):
            reasons.append(f"write run {index + 1} changed auth.json")
        if row.get("global_config_sha256_before") != row.get("global_config_sha256_after"):
            reasons.append(f"write run {index + 1} changed global config")
    if len({row.get("child_thread_id") for row in result}) != len(result):
        reasons.append("write runs must have unique child threads")
    if len({row.get("target") for row in result}) != len(result):
        reasons.append("write runs must have disjoint targets")
    return result


def evaluate_g4(doc: dict[str, Any], probe_dir: Path | None = None) -> tuple[str, list[str]]:
    reasons: list[str] = []
    if doc.get("schema") != "hl-loop-g4-serial-write/v2":
        reasons.append("schema missing or mismatched")
    if probe_dir is not None:
        expected = _sha256(probe_dir / "g3-readonly-week.json") if (probe_dir / "g3-readonly-week.json").is_file() else None
        if (
            doc.get("purpose") != "formal"
            or doc.get("parent_evidence_sha256") != {"g3": expected}
            or doc.get("trust_manifest_sha256") != _current_trust_manifest_sha256(probe_dir)
            or doc.get("gateway_profile_sha256") != _current_gateway_profile_sha256(probe_dir)
        ):
            reasons.append("G4 is not bound to the current formal G3 evidence")
    runs = _write_runs(doc, G4_REQUIRED_RUNS, reasons)
    if any(row.get("mode") != "serial" for row in runs):
        reasons.append("G4 contains a non-serial write run")
    _checks_true(doc.get("checks"), {
        "required_repetitions", "all_runs_ok", "no_temporal_overlap",
        "auth_unchanged", "global_config_unchanged",
    }, reasons)
    timestamps = [(_timestamp(row.get("started_at")), _timestamp(row.get("completed_at"))) for row in runs]
    if any(start is None or end is None or start > end for start, end in timestamps):
        reasons.append("serial run timestamps are invalid")
    elif any(timestamps[i][1] > timestamps[i + 1][0] for i in range(len(timestamps) - 1)):
        reasons.append("serial write runs overlap")
    return ("IN_PROGRESS", reasons) if reasons else ("PASSED", [])


def evaluate_g5(doc: dict[str, Any], probe_dir: Path | None = None) -> tuple[str, list[str]]:
    reasons: list[str] = []
    if doc.get("schema") != "hl-loop-g5-concurrent-write/v2":
        reasons.append("schema missing or mismatched")
    if probe_dir is not None:
        expected = {
            name: _sha256(probe_dir / filename) if (probe_dir / filename).is_file() else None
            for name, filename in (("g3", "g3-readonly-week.json"), ("g4", "g4-serial-write.json"))
        }
        if (
            doc.get("purpose") != "formal"
            or doc.get("parent_evidence_sha256") != expected
            or doc.get("trust_manifest_sha256") != _current_trust_manifest_sha256(probe_dir)
            or doc.get("gateway_profile_sha256") != _current_gateway_profile_sha256(probe_dir)
        ):
            reasons.append("G5 is not bound to the current formal G3/G4 evidence")
    runs = _write_runs(doc, G5_REQUIRED_RUNS, reasons)
    if any(row.get("mode") != "concurrent" for row in runs):
        reasons.append("G5 contains a non-concurrent write run")
    _checks_true(doc.get("checks"), {
        "required_concurrency", "all_runs_ok", "observed_overlap",
        "disjoint_targets", "auth_unchanged", "global_config_unchanged",
        "serial_integration_verified",
    }, reasons)
    if doc.get("overlap_basis") != "subagent_start_to_subagent_stop_attestation":
        reasons.append("G5 overlap must be derived from child attestation intervals")
    if doc.get("barrier_released_with_child_starts") != G5_REQUIRED_RUNS:
        reasons.append("G5 child-overlap barrier was not reached by all 16 children")
    intervals = [
        (_timestamp(row.get("child_started_at")), _timestamp(row.get("child_completed_at")))
        for row in runs
    ]
    if any(start is None or end is None or start > end for start, end in intervals):
        reasons.append("concurrent run timestamps are invalid")
        measured_overlap = 0
    else:
        points = [value for interval in intervals for value in interval]
        measured_overlap = max(
            (sum(start <= point < end for start, end in intervals) for point in points),
            default=0,
        )
    if (
        not isinstance(doc.get("max_overlap"), int)
        or doc.get("max_overlap", 0) < G5_REQUIRED_RUNS
        or doc.get("max_overlap") != measured_overlap
    ):
        reasons.append("concurrent wave lacks measured overlap")
    return ("IN_PROGRESS", reasons) if reasons else ("PASSED", [])


