"""Audit livelock exit (v3 rule five; SPEC-API 3.9).

Persisted JSON state shape:
{packet_id: {"interceptions": [{"ts": ..., "finding_digest": ...}],
             "channel_closed": bool,
             "arbitrations": [{"ts": ..., "outcome": ...}]}}

First consecutive interception -> SHORT_CIRCUIT_REPAIR. Second consecutive
(channel not yet closed) -> FORCE_ESCALATE and the channel closes. Further
interceptions while closed keep returning FORCE_ESCALATE.
"""
from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path

from .filelock import exclusive_file_lock

ACTION_REPAIR = "SHORT_CIRCUIT_REPAIR"
ACTION_ESCALATE = "FORCE_ESCALATE"


class Action:
    """Namespace mirror of the module-level action constants."""

    SHORT_CIRCUIT_REPAIR = ACTION_REPAIR
    FORCE_ESCALATE = ACTION_ESCALATE


def _utc_now_iso() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


class LivelockGuard:
    def __init__(self, state_path: Path) -> None:
        self.state_path = Path(state_path)
        self.lock_path = self.state_path.with_name(self.state_path.name + ".lock")

    # -- persistence ---------------------------------------------------
    def _load(self) -> dict:
        if not self.state_path.exists():
            return {}
        try:
            doc = json.loads(self.state_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return {}
        return doc if isinstance(doc, dict) else {}

    def _save(self, state: dict) -> None:
        self.state_path.parent.mkdir(parents=True, exist_ok=True)
        tmp = self.state_path.with_name(self.state_path.name + ".tmp")
        tmp.write_text(json.dumps(state, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        tmp.replace(self.state_path)

    def _entry(self, state: dict, packet_id: str) -> dict:
        entry = state.get(packet_id)
        if not isinstance(entry, dict):
            entry = {"interceptions": [], "channel_closed": False, "arbitrations": []}
            state[packet_id] = entry
        entry.setdefault("interceptions", [])
        entry.setdefault("channel_closed", False)
        entry.setdefault("arbitrations", [])
        return entry

    # -- protocol -------------------------------------------------------
    def record_interception(self, packet_id: str, finding_summary: str) -> str:
        """Record one must_fix interception; return the mandated action."""
        with exclusive_file_lock(self.lock_path):
            state = self._load()
            entry = self._entry(state, packet_id)
            entry["interceptions"].append(
                {"ts": _utc_now_iso(), "finding_digest": finding_summary}
            )
            if entry["channel_closed"]:
                action = ACTION_ESCALATE
            elif len(entry["interceptions"]) == 1:
                action = ACTION_REPAIR
            else:
                action = ACTION_ESCALATE
                entry["channel_closed"] = True
            self._save(state)
            return action

    def record_arbitration(self, packet_id: str, outcome: str) -> dict:
        """Record the human/arbiter outcome for a disputed interception."""
        if outcome not in ("false_positive", "confirmed"):
            raise ValueError(f"unknown arbitration outcome: {outcome!r}")
        with exclusive_file_lock(self.lock_path):
            state = self._load()
            entry = self._entry(state, packet_id)
            ts = _utc_now_iso()
            entry["arbitrations"].append({"ts": ts, "outcome": outcome})
            if outcome == "false_positive":
                interceptions = entry["interceptions"]
                digest = interceptions[-1]["finding_digest"] if interceptions else None
                result = {
                    "lessons_entry": {
                        "packet_id": packet_id,
                        "kind": "audit_false_positive",
                        "finding_digest": digest,
                        "ts": ts,
                    },
                    "canary_retest": True,
                    "disputed_dimensions_note_only": True,
                }
            else:
                result = {
                    "lessons_entry": None,
                    "canary_retest": False,
                    "disputed_dimensions_note_only": False,
                }
            self._save(state)
            return result

    def is_channel_closed(self, packet_id: str) -> bool:
        with exclusive_file_lock(self.lock_path):
            entry = self._load().get(packet_id)
            return bool(isinstance(entry, dict) and entry.get("channel_closed"))

    def reset(self, packet_id: str) -> None:
        """Remove all persisted state for one packet."""
        with exclusive_file_lock(self.lock_path):
            state = self._load()
            if packet_id in state:
                del state[packet_id]
                self._save(state)

