from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from pathlib import Path


GENESIS = "GENESIS"


def _canonical_hash(record: dict) -> str:
    body = {key: value for key, value in record.items() if key != "hash"}
    raw = json.dumps(
        body, sort_keys=True, separators=(",", ":"), ensure_ascii=False,
    ).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def verify_chain_bytes(raw: bytes) -> list[dict]:
    """Parse and verify a complete hook JSONL chain from GENESIS."""
    if raw and not raw.endswith(b"\n"):
        raise ValueError("hook evidence chain has an unterminated tail")
    records: list[dict] = []
    previous = GENESIS
    for expected_seq, line in enumerate(raw.splitlines(), 1):
        if not line.strip():
            raise ValueError("hook evidence chain contains a blank record")
        try:
            record = json.loads(line.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ValueError("hook evidence chain contains malformed JSON") from exc
        if not isinstance(record, dict):
            raise ValueError("hook evidence record is not an object")
        if record.get("seq") != expected_seq:
            raise ValueError("hook evidence sequence is not contiguous")
        if record.get("prev_hash") != previous:
            raise ValueError("hook evidence prev_hash linkage is broken")
        digest = record.get("hash")
        if not isinstance(digest, str) or digest != _canonical_hash(record):
            raise ValueError("hook evidence record hash is invalid")
        previous = digest
        records.append(record)
    return records


@dataclass(frozen=True)
class ChainSnapshot:
    raw: bytes
    records: tuple[dict, ...]


def capture_chain(path: Path) -> ChainSnapshot:
    raw = path.read_bytes() if path.is_file() else b""
    return ChainSnapshot(raw=raw, records=tuple(verify_chain_bytes(raw)))


def appended_chain_records(path: Path, before: ChainSnapshot) -> list[dict]:
    """Verify old bytes are an exact prefix and return newly appended records."""
    after = path.read_bytes() if path.is_file() else b""
    if not after.startswith(before.raw):
        raise ValueError("hook evidence chain was truncated or its old prefix changed")
    records = verify_chain_bytes(after)
    if records[:len(before.records)] != list(before.records):
        raise ValueError("hook evidence chain prefix records changed")
    return records[len(before.records):]


def record_hashes(records: list[dict]) -> list[str]:
    return [str(record["hash"]) for record in records]


